  "signal_basis": {
    "component_id": "C054_signal_basis",
    "value": "Canary assessment tracks predicted-phase and overall tail changes, failures and unfinished exports against predefined operating bounds. Expansion stops and the canary is reverted if those bounds are breached or monitoring cannot enforce them.",
    "scope": "A proposed assessment and safety gate for deployment decisions, with bounds defined against comparable baseline traffic; no numerical thresholds or observed results are supplied.",
